"""Definition-only final receipt consumer. Absent FINAL-BINDING refuses operation."""
from bindings import *
from policy import validate_partition

def validate_source_review(path,digest):
 binding=final_binding();need({'path':str(path),'sha256':digest}==binding['sourceReview'],'exact final receipt reference')
 v=private_json(path,digest,131072);need(v.get('status')=='APPROVED_SOURCE_ONLY','draft receipt is never executable')
 need(type(v['schemaVersion']) is int and v['schemaVersion']==1 and v['kind']=='root-final-viewer-tools-source-review' and v['scope']=='configured-startup-control-join-plus-ordinary-admission-teardown','final combined receipt kind')
 tip=binding['sourceTIP'];viewer=binding['viewerSourceTIP']
 need(v['sourceTIP']==v['archiveCommit']==tip and v['viewerSourceTIP']==v['reviewedCodeTIP']==viewer and v['toolTIP']==TOOL_TIP and v['deployedToolTIP']==OLD_TOOL_TIP and v['deployedViewerSourceTIP']==v['codeReviewBase']==VIEWER_TIP and v['backendTIP']==PRODUCT and v['archiveChangesDocsOnly'] is True,'separate deployed/new component pins')
 need(commit(tip)==tip and commit(viewer)==viewer and git(S,'rev-parse','HEAD').decode().strip()==tip and v['sourceCheckout']==str(S),'held final checkout')
 for ancestor,descendant in ((VIEWER_TIP,viewer),(TOOL_TIP,viewer),(viewer,tip)):git(S,'merge-base','--is-ancestor',ancestor,descendant)
 rows=raw_diff(VIEWER_TIP,tip);validate_partition([{k:r[k] for k in ('path','status','oldMode','newMode')} for r in rows],v['promotionPaths'],v['notPromoted']);need([r['path'] for r in rows]==v['canonicalPaths'],'exact full canonical paths')
 patch=git(S,'diff','--binary','--full-index','--no-renames',VIEWER_TIP,tip);need(sha(patch)==v['canonicalPatch']['sha256'] and patch==check_ref(v['canonicalPatch']),'canonical binary full-index patch')
 for row in raw_diff(viewer,tip):need(row['path'].startswith('docs/superpowers/') and row['status'] in ('A','M') and row['newMode']=='100644','archive docs-only')
 b,h,records=history();need(set(v['fileSources'])==set(COPY_PATHS),'exact four file sources')
 tr,_=tree(tip)
 prime_blobs(tip,{n for n in tr if n.startswith('web-client/')}|BUILD_INPUTS|set(RUNTIME[1:])|set(COPY_PATHS))
 prime_blobs(TOOL_TIP,list(TOOLS));prime_blobs(viewer,[n for n in COPY_PATHS if n not in TOOLS])
 prime_blobs(PRODUCT,set(RUNTIME[1:4])|BUILD_INPUTS);prime_blobs(MODULE_TIP,[RUNTIME[4]])
 for name,pin in v['fileSources'].items():
  exact(pin,('sha256','bytes','gitMode','oldSha256','oldBytes','oldGitMode','oldFilesystemMode','oldSourceTIP','componentTIP'))
  component=TOOL_TIP if name in TOOLS else viewer;oldtip=OLD_TOOL_TIP if name in TOOLS else VIEWER_TIP;raw=blob(tip,name);old=blob(oldtip,name)
  need(pin['componentTIP']==component and pin['oldSourceTIP']==oldtip and raw==blob(component,name) and sha(raw)==pin['sha256'] and type(pin['bytes']) is int and len(raw)==pin['bytes'],'reviewed component bytes')
  need(pin['gitMode']==pin['oldGitMode']=='100644' and pin['oldSha256']==sha(old)==b['regularFiles'][name]['sha256'] and type(pin['oldBytes']) is int and len(old)==pin['oldBytes'] and type(pin['oldFilesystemMode']) is int and pin['oldFilesystemMode']==b['regularFiles'][name]['filesystemMode'],'historical exact preimage/mode')
 need(type(v['expectedPreRegularCount']) is int and type(v['expectedPostRegularCount']) is int and v['expectedPreRegularCount']==v['expectedPostRegularCount']==len(b['regularFiles'])==1016,'known map no expansion')
 need(set(v['unchangedComponentTrees'])=={'signal-server','python-host'},'unchanged backend tree coverage')
 for name,pin in v['unchangedComponentTrees'].items():need(pin['unchangedFromViewerSource'] is True and git(S,'rev-parse',tip+':'+name).decode().strip()==pin['treeOID']==git(S,'rev-parse',VIEWER_TIP+':'+name).decode().strip(),'backend unchanged')
 need(git(S,'rev-parse',tip+':web-client').decode().strip()==v['viewerTreeOID']==git(S,'rev-parse',viewer+':web-client').decode().strip(),'Viewer exact component tree')
 for name in (*RUNTIME[1:4],*BUILD_INPUTS):need(blob(tip,name)==blob(PRODUCT,name),'immutable helper/fault/sampler/builder drift')
 need(blob(tip,RUNTIME[4])==blob(MODULE_TIP,RUNTIME[4])==regular(R/'process_observation_diagnostics.py')[0],'approved diagnostics bytes')
 for name in {n for n in tr if n.startswith('web-client/')}|BUILD_INPUTS:
  if name not in COPY_PATHS:need(name in b['regularFiles'] and sha(blob(tip,name))==b['regularFiles'][name]['sha256'],'non-published build input differs from deployed source')
 check_ref({k:v['historicalToolSourceReceipt'][k] for k in ('path','sha256')});need(v['historicalToolSourceReceipt']['executable'] is False,'historical receipt not authority')
 exact(v['toolReviews'],('taskReview','initialFinalReview','finalFixReview'))
 for item in v['toolReviews'].values():check_ref({k:item[k] for k in ('path','sha256')})
 need(v['toolReviews']['initialFinalReview']['classification']=='ChangesRequested-one-P2-closed-by-scoped-fix' and v['toolReviews']['finalFixReview']['classification']=='Approved-scoped-fix-no-new-findings','tool review closure')
 exact(v['viewerReviews'],('taskReview','finalReview'))
 for item in v['viewerReviews'].values():check_ref({k:item[k] for k in ('path','sha256')});need(item['classification']=='Approved','Viewer review approval')
 check_ref(v['actualPreimageObservation']);check_ref(v['finalReviewPackage'])
 for ref in v['archivedEvidenceIndices']:check_ref(ref)
 check_ref({k:v['supersedesReceipt'][k] for k in ('path','sha256')})
 actual=v['actualR5Context'];need(actual['expectedServices']==b['expectedServices'] and actual['runtimeAssets']==b['assets'],'actual retained R5 deployment')
 for field,name in (('packageManifestSHA256','r5PackageManifest'),('frozenSHA256','r5Frozen'),('assetReviewSHA256','r5AssetReview'),('applySHA256','r5Apply'),('reloadSHA256','r5Reload'),('readinessSHA256','r5Readiness')):need(actual[field]==h['records'][name]['sha256'],'historical deployment lineage')
 need(v['failedHistory']==FAILURES and v['thirdFailure']['sha256']==THIRD_FAILURE and v['primaryPreserve']['head']==b['head'] and v['primaryPreserve']['indexSHA256']==b['indexSha256'],'history/primary preserved')
 dirty=b['exceptions'][:4];need(git(S,'diff','--name-only','-z').split(b'\0')[:-1]==[n.encode() for n in dirty] and not git(S,'diff','--cached','--name-only','-z'),'source four dirty/staged guard')
 for name in dirty:need(sha(checked_file(S,name)[0])==b['regularFiles'][name]['sha256'],'dirty source docs preserved')
 need(git(S,'ls-files','--others','--exclude-standard','-z').split(b'\0')[:-1]==[b'signal-server/node_modules'] and nodeinfo(S/'signal-server/node_modules')==b['sourceNodeModules'],'source node link metadata only')
 return dict(v,copyPaths=list(COPY_PATHS))
